  "outcome": "escalate",
  "rationale": "This claim must be escalated because an automated fraud flag was raised for an inflated estimate. Section 7.3 governs this situation by requiring escalation when the claimed amount is substantially higher than the usual repair cost. The key fact is that the claimed damage of $19,880.00 exceeds twice the typical repair cost.",
  "citations": [
    {
      "clause_id": "STD-7.3",
      "quote": "If the amount claimed is substantially higher than the usual cost of repairing the damage described, or is not supported by the itemized estimate, the claim must be escalated for review."
    }
  ]
}
